import os
import re
import struct
import tempfile
import unittest
from pathlib import Path
from unittest import mock

from pyacorndfs import disasm
from pyacorndfs.dfs import DISK_SIZE, acorn_dfs

PROGRAM = bytes([0xA9, 0x00, 0x60])  # LDA #0 : RTS


def instructions(listing):
    """Lower-case mnemonic + operand lines, ignoring py8dis' byte comments."""
    return [line.split(";")[0].strip() for line in listing.splitlines() if re.match(r"\s+[a-z]{3}\b", line) and not line.strip().startswith("org")]


def make_ssd(path, name=b"PROG   ", ext=b"$", load=0x1900, exec_=0x1900, extra=0, data=PROGRAM):
    image = bytearray(DISK_SIZE)
    image[:8] = b"DISASM  "
    struct.pack_into("4sBBBB", image, 256, b"    ", 0, 8, 3, 0x20)
    struct.pack_into("7sc", image, 8, name, ext)
    struct.pack_into("HHHBB", image, 264, load & 0xFFFF, exec_ & 0xFFFF, len(data), extra, 2)
    image[2 * 256 : 2 * 256 + len(data)] = data
    Path(path).write_bytes(image)


@unittest.skipUnless(disasm.is_available(), "py8dis submodule not checked out")
class DisassembleTest(unittest.TestCase):
    def test_listing_contains_expected_opcodes(self):
        result = disasm.disassemble(PROGRAM, 0x1900, 0x1900, "PROG")
        self.assertIn("org &1900", result.listing)
        self.assertEqual(instructions(result.listing), ["lda #0", "rts"])
        self.assertIn("load(0x1900", result.control_script)
        self.assertIn("entry(0x1900)", result.control_script)
        self.assertIsNone(result.listing_path)

    def test_writes_binary_script_and_6502_side_by_side(self):
        with tempfile.TemporaryDirectory() as directory:
            result = disasm.disassemble(PROGRAM, 0x1900, 0x1900, "PROG", directory)
            self.assertEqual(result.listing_path, Path(directory) / "PROG.6502")
            self.assertEqual((Path(directory) / "PROG").read_bytes(), PROGRAM)
            self.assertEqual(result.listing_path.read_text(), result.listing)
            self.assertEqual(result.script_path.read_text(), result.control_script)

    def test_io_processor_address_is_masked_and_noted(self):
        result = disasm.disassemble(PROGRAM, 0xFFFF1900, 0xFFFF1900, "PROG")
        self.assertIn("org &1900", result.listing)
        self.assertIn("I/O processor &1900", result.listing)

    def test_acorn_dfs_disassemble_writes_next_to_image(self):
        with tempfile.TemporaryDirectory() as directory:
            ssd = os.path.join(directory, "test.ssd")
            make_ssd(ssd, extra=0x0C | 0xC0)  # load and exec high bits = I/O processor
            image = acorn_dfs(ssd)
            self.assertEqual(image.disk_info[0]["file_info"][0]["load_&"], 0xFFFF1900)
            result = image.disassemble(0, 0)
            self.assertEqual(result.listing_path, Path(directory) / "PROG.6502")
            self.assertEqual(instructions(result.listing), ["lda #0", "rts"])

    def test_non_dollar_directory_goes_in_the_name(self):
        with tempfile.TemporaryDirectory() as directory:
            ssd = os.path.join(directory, "test.ssd")
            make_ssd(ssd, ext=b"B")
            result = acorn_dfs(ssd).disassemble(0, 0)
            self.assertEqual(result.listing_path.name, "PROG.B.6502")

    def test_saved_control_script_reruns_from_its_own_directory(self):
        import subprocess
        import sys

        with tempfile.TemporaryDirectory() as directory:
            result = disasm.disassemble(PROGRAM, 0x1900, 0x1900, "PROG", directory)
            env = dict(os.environ, PYTHONPATH=str(disasm.find_py8dis()))
            rerun = subprocess.run([sys.executable, str(result.script_path)], cwd="/", env=env, capture_output=True, text=True, check=True)
            self.assertEqual(rerun.stdout, result.listing)

    def test_file_past_ffff_is_truncated_and_full_binary_kept(self):
        data = bytes([0xEA] * 0xF + [0x60] + [0xEA] * 0x10)  # NOPs, RTS at &FFFF, then 16 bytes past the top
        with tempfile.TemporaryDirectory() as directory:
            (Path(directory) / "BIG").write_bytes(b"full save")
            result = disasm.disassemble(data, 0xFFF0, 0xFFF0, "BIG", directory)
            self.assertEqual((Path(directory) / "BIG").read_bytes(), b"full save")
            self.assertEqual((Path(directory) / "BIG.trunc").read_bytes(), data[:0x10])
            self.assertEqual(result.listing_path.name, "BIG.6502")
            self.assertIn("truncated to &10 bytes", result.listing)

    def test_py8dis_failure_raises(self):
        with mock.patch.object(disasm, "make_control_script", return_value="raise SystemExit(3)\n"):
            with self.assertRaises(disasm.DisasmError):
                disasm.disassemble(PROGRAM, 0x1900, 0x1900, "PROG")


class AddressTest(unittest.TestCase):
    def test_split_address(self):
        self.assertEqual(disasm.split_address(0x1900), (0x1900, 0))
        self.assertEqual(disasm.split_address(0xFFFF8023), (0x8023, 0xFFFF))
        self.assertEqual(disasm.split_address(0x21900), (0x1900, 2))

    def test_only_ffff_high_bits_mean_io_processor(self):
        self.assertIn("I/O processor", disasm.describe_address(0xFFFF1900))
        self.assertNotIn("I/O processor", disasm.describe_address(0x16550))
        self.assertEqual(disasm.describe_address(0x1900), "&1900")

    def test_entry_uses_exec_inside_file_else_load(self):
        self.assertEqual(disasm.choose_entry(0x1900, 0x1902, 3), 0x1902)
        self.assertEqual(disasm.choose_entry(0x1900, 0xFFFF1902, 3), 0x1902)
        self.assertEqual(disasm.choose_entry(0x1900, 0x8023, 3), 0x1900)

    def test_safe_name(self):
        self.assertEqual(disasm.safe_name("A/B"), "A_B")
        self.assertEqual(disasm.safe_name("  "), "UNNAMED")

    def test_unavailable_when_not_found(self):
        with mock.patch.object(disasm, "_SUBMODULE_PACKAGE", Path("/nonexistent")), mock.patch.dict(os.environ, {disasm.PY8DIS_ENV: ""}):
            self.assertFalse(disasm.is_available())
            with self.assertRaises(disasm.DisasmError):
                disasm.disassemble(PROGRAM, 0x1900, 0x1900, "PROG")


